using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class WideAudit {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string Out=>Repo+"/Docs/검수/2026-11-06_B345_WideInterior/";
 static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 static Vector3 V(JToken p)=>new Vector3((float)p[0],(float)p[1],(float)p[2]);
 public static object Check(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit scene required");var original=SceneManager.GetActiveScene().path;var rows=new List<object>();var errors=new List<string>();
  try{foreach(string f in new[]{"B5","B4","B3"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Stealth.unity");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith(f+"_Stealth_Level"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var baseline=JObject.Parse(File.ReadAllText(Out+"Before/"+f+"_snapshot.json"));var by=all.GroupBy(P).ToDictionary(g=>g.Key,g=>new Queue<Transform>(g));int preserved=0,moved=0;
   foreach(var b in baseline["transforms"]){string path=(string)b["path"];if(path.Contains("/Arched_Interior"))continue;if(!by.ContainsKey(path)||by[path].Count==0){errors.Add("Missing "+path);continue;}var t=by[path].Dequeue();if(Vector3.Distance(t.localEulerAngles,V(b["rotation"]))>.001f||Vector3.Distance(t.localScale,V(b["scale"]))>.0001f||t.gameObject.activeSelf!=(bool)b["active"])errors.Add("Rotation/scale/active changed "+path);if(Vector3.Distance(t.localPosition,V(b["position"]))>.001f)moved++;preserved++;}
   var cases=root.GetComponentsInChildren<LODGroup>(true).Where(g=>g.GetComponentsInChildren<MeshFilter>(true).Any(m=>m.sharedMesh&&AssetDatabase.GetAssetPath(m.sharedMesh).EndsWith("SD_SpecimenCase.fbx"))).ToArray();int pairs=0;
   for(int i=0;i<cases.Length;i++){foreach(var r in cases[i].GetComponentsInChildren<Renderer>(true))if(r.sharedMaterials.Any(m=>!m||!m.name.StartsWith("SW_Case_")))errors.Add("Case wear missing "+cases[i].name);for(int j=i+1;j<cases.Length;j++)if(Vector3.Distance(cases[i].transform.position,cases[j].transform.position)<1.05f&&cases[i].GetComponentInChildren<Renderer>().sharedMaterial==cases[j].GetComponentInChildren<Renderer>().sharedMaterial)pairs++;}
   var wm=root.transform.Find("Wall_Surface_Wear").GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().ToArray();foreach(var m in wm)foreach(string slot in new[]{"_BaseMap","_BumpMap","_MetallicGlossMap"})if(!m.GetTexture(slot))errors.Add("Wall texture missing "+m.name+" "+slot);
   Physics.SyncTransforms();var arches=root.transform.Find("Arched_Interior");var clashes=new List<object>();foreach(var c in arches.GetComponentsInChildren<BoxCollider>()){if(c.name.StartsWith("Core_Junction"))continue;var hits=Physics.OverlapBox(c.bounds.center,c.bounds.extents-Vector3.one*.025f,Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(h=>!h.transform.IsChildOf(arches)&&!h.transform.root.name.StartsWith("Player")).Select(h=>P(h.transform)).ToArray();if(hits.Length>0)clashes.Add(new{name=c.name,hits});}
   rows.Add(new{floor=f,preservedOriginalRotationScaleActive=preserved,translatedLocalTransforms=moved,caseCount=cases.Length,equalWearNeighborPairs=pairs,archCollisions=clashes,activeLights=root.GetComponentsInChildren<Light>().Count(l=>l.enabled),disabledLights=root.GetComponentsInChildren<Light>().Count(l=>!l.enabled),archLights=arches.GetComponentsInChildren<Light>().Length,reflectionProbes=root.GetComponentsInChildren<ReflectionProbe>().Length,activeModels=all.Select(t=>t.GetComponent<MeshFilter>()).Where(m=>m&&m.sharedMesh&&m.GetComponent<Renderer>().enabled).Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).Distinct().Where(p=>p.Contains("WC_")||p.Contains("WA_")).ToArray()});
  }}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(Out+"art_audit.json",JsonConvert.SerializeObject(new{rows,errors},Formatting.Indented));return new{rows,errors};}
}
